# Break My Fix finding 1, generated by Tracefix: badge returns a wrong value.
# Property (comment): With label, message and color the URL path has exactly the three components {label}-{message}-{color}, so dashes inside label/message must not create extra separators
# Quote: Either {message}-{color} or {label}-{message}-{color}
# Run it with pytest: it fails for as long as the code breaks this property.

import re

from clldutils.badge import badge


def test_break_my_fix_1() -> None:
    subject = ''
    status = ''
    color = 'green'
    message = '1-2'
    label = 'a-b'
    fmt = 'svg'
    markdown = False
    # The property applies to this input: markdown == False and fmt == 'svg' and label != '' and message != '' and color != '' and subject == '' and status == '' and '-' not in color and not label.startswith('-') and not label.endswith('-') and not message.startswith('-') and not message.endswith('-') and '--' not in label and '--' not in m
    result = badge(subject=subject, status=status, color=color, message=message, label=label, fmt=fmt, markdown=markdown)
    assert (len(re.split(r'(?<!-)-(?!-)', result.split('?')[0][len('https://img.shields.io/badge/'):-4])) == 3 and re.split(r'(?<!-)-(?!-)', result.split('?')[0][len('https://img.shields.io/badge/'):-4])[-1] == color)
